{"format_version":1,"query":"runWatch runWorkspaceWatchPass runSupervisedWatch watch once","repo_root":"/Users/thomi/.codex/worktrees/04638663-839c-4e0a-9303-5b0278f98cd0/entire-brain","commit":"88519f77572ec1ad2b7cb93ffa81abdb1f303262","tree":"1e3eef2478afa64f2d64d45fb4b3a1b4c3daacd1","profile":"full","results":[{"rank":1,"score":133.546,"file_path":"internal/cli/workspace.go","start_line":341,"end_line":388,"focus_line":374,"snippet_start_line":341,"snippet_end_line":388,"symbol_start_line":374,"symbol_end_line":388,"language":"Go","kind":"function","symbol_id":"gh/entireio/entire-brain:Go:internal/cli/workspace.go:function:runSupervisedWatch","symbol_name":"runSupervisedWatch","qualified_name":"runSupervisedWatch","signature":"func runSupervisedWatch(ctx context.Context, cmd *cobra.Command, opts Options, w watchCommandOptions) error","signals":["body","exact-symbol","symbol-name","signature","constraint:entity","exact-code-token","graph:callers","complete-symbol","contiguous-span"],"snippet":"func newWorkspaceWatchCommand(opts Options) *cobra.Command {\n\tw := defaultWatchOptions()\n\tcmd := &cobra.Command{\n\t\tUse:   \"watch [workspace]\",\n\t\tShort: \"Keep every repo in a workspace fresh automatically (deterministic refresh is free; agent steps gated)\",\n\t\tLong: \"Keep every repo in a workspace fresh automatically.\\n\\n\" +\n\t\t\t\"With a workspace name, watches that one workspace with the flags given here.\\n\\n\" +\n\t\t\t\"With NO workspace name this is SUPERVISED mode: it watches every workspace `setup`\\n\" +\n\t\t\t\"has recorded in the machine-level watch plan, each with its own interval, distill\\n\" +\n\t\t\t\"cadence, agent, model, effort and session cap. That is the form the installed\\n\" +\n\t\t\t\"background service runs, and it is why the installed unit is byte-identical on\\n\" +\n\t\t\t\"every machine: nothing about which repo ran `setup` reaches the unit file.\",\n\t\tArgs: cobra.MaximumNArgs(1),\n\t\tRunE: func(cmd *cobra.Command, args []string) error {\n\t\t\tif len(args) == 0 {\n\t\t\t\treturn runSupervisedWatch(cmd.Context(), cmd, opts, w)\n\t\t\t}\n\t\t\treturn runWorkspaceWatch(cmd.Context(), cmd, opts, w, args[0])\n\t\t},\n\t}\n\tbindWatchFlags(cmd, &w)\n\treturn cmd\n}\n\n// runSupervisedWatch is the ONE machine-wide watcher. It re-reads the watch plan\n// on every outer pass, so a repo that runs `setup` while the daemon is already\n// running joins the rotation WITHOUT the unit file changing and therefore\n// without the service being unloaded and reloaded under an in-flight refresh.\n//\n// An empty plan is not an error. A KeepAlive/Restart=always unit that exits\n// non-zero because nothing is registered yet is a restart loop, and the honest\n// state of a machine mid-onboarding is \"nothing to watch yet\", so it says that\n// once per pass and keeps waiting.\nfunc runSupervisedWatch(ctx context.Context, cmd *cobra.Command, opts Options, w watchCommandOptions) error {\n\tif w.distillJobs <= 0 {\n\t\treturn fmt.Errorf(\"--jobs must be greater than 0\")\n\t}\n\tnow := opts.Now\n\tif now == nil {\n\t\tnow = time.Now\n\t}\n\tctx, stop := watchSignalContext(ctx)\n\tdefer stop()\n\tonePass := func(workspaceName string, pass watchCommandOptions, agentCalls *int) error {\n\t\treturn runWorkspaceWatchPass(ctx, cmd, opts, pass, workspaceName, now, agentCalls)\n\t}\n\treturn supervisedWatchLoop(ctx, cmd.OutOrStdout(), opts.Env, w, onePass, daemonLogMaintainer(opts.Env))\n}","merged_ranks":[1,3,4]},{"rank":2,"score":120.4741,"file_path":"internal/cli/watch.go","start_line":203,"end_line":205,"focus_line":203,"snippet_start_line":203,"snippet_end_line":205,"symbol_start_line":203,"symbol_end_line":205,"language":"Go","kind":"function","symbol_id":"gh/entireio/entire-brain:Go:internal/cli/watch.go:function:watchSignalContext","symbol_name":"watchSignalContext","qualified_name":"watchSignalContext","signature":"func watchSignalContext(ctx context.Context) (context.Context, context.CancelFunc)","signals":["graph:calls","graph:outgoing","graph:callers"],"snippet":"func watchSignalContext(ctx context.Context) (context.Context, context.CancelFunc) {\n\treturn signal.NotifyContext(ctx, os.Interrupt, syscall.SIGTERM)\n}"},{"rank":3,"score":108.4267,"file_path":"internal/cli/watch.go","start_line":150,"end_line":183,"focus_line":177,"snippet_start_line":150,"snippet_end_line":183,"symbol_start_line":150,"symbol_end_line":183,"language":"Go","kind":"function","symbol_id":"gh/entireio/entire-brain:Go:internal/cli/watch.go:function:runWatch","symbol_name":"runWatch","qualified_name":"runWatch","signature":"func runWatch(ctx context.Context, cmd *cobra.Command, opts Options, w watchCommandOptions, target string) error","signals":["body","exact-symbol","symbol-name","symbol-usage","complete-symbol"],"snippet":"func runWatch(ctx context.Context, cmd *cobra.Command, opts Options, w watchCommandOptions, target string) error {\n\tif w.interval <= 0 {\n\t\tw.interval = 5 * time.Minute\n\t}\n\tif w.distillJobs <= 0 {\n\t\treturn fmt.Errorf(\"--jobs must be greater than 0\")\n\t}\n\tnow := opts.Now\n\tif now == nil {\n\t\tnow = time.Now\n\t}\n\trepoDir, local, err := resolveLocalTargetRepoDir(ctx, opts.Runner, target)\n\tif err != nil {\n\t\treturn err\n\t}\n\tif !local {\n\t\treturn fmt.Errorf(\"watch requires a local repository path: %s\", target)\n\t}\n\tstorage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)\n\tif err != nil {\n\t\treturn err\n\t}\n\tcursorPath := filepath.Join(filepath.Dir(storage.HeadPath), \"watch.json\")\n\tsteps := watchStepsForRepo(cmd, opts, w, repoDir, now)\n\t// Wire SIGINT/SIGTERM so a long-running daemon stops cleanly between ticks instead of being killed\n\t// mid-refresh; this is what makes the loop's ctx-cancel paths live (the root command runs with a\n\t// Background context otherwise).\n\tctx, stop := watchSignalContext(ctx)\n\tdefer stop()\n\tfmt.Fprintf(cmd.OutOrStdout(), \"[watch] %s — interval %s, distill=%v (every %s, agent=%s, jobs=%d, model=%q, max-sessions=%s, run-budget=%s)\\n\",\n\t\tstorage.Key, w.interval, w.distill, w.distillEvery, w.distillAgent, w.distillJobs, w.model,\n\t\twatchCapLabel(w.distillMaxSessions), watchCapLabel(w.budget))\n\treturn watchLoop(ctx, cmd.OutOrStdout(), w, cursorPath, steps)\n}"},{"rank":4,"score":102.557,"file_path":"internal/cli/watch.go","start_line":230,"end_line":309,"focus_line":230,"snippet_start_line":230,"snippet_end_line":231,"symbol_start_line":230,"symbol_end_line":359,"language":"Go","kind":"function","symbol_id":"gh/entireio/entire-brain:Go:internal/cli/watch.go:function:watchTick","symbol_name":"watchTick","qualified_name":"watchTick","signature":"func watchTick(ctx context.Context, out io.Writer, w watchCommandOptions, cursorPath string, steps watchSteps, agentCalls *int)","signals":["graph:calls","graph:outgoing","graph:callers"],"snippet":"func watchTick(ctx context.Context, out io.Writer, w watchCommandOptions, cursorPath string, steps watchSteps, agentCalls *int) {\n\t// Short-term memory first, every tick: cheap (change detection + only"},{"rank":5,"score":94.3243,"file_path":"internal/cli/setup_daemon_concurrency_test.go","start_line":360,"end_line":364,"focus_line":362,"snippet_start_line":361,"snippet_end_line":362,"symbol_start_line":356,"symbol_end_line":373,"language":"Go","kind":"function","symbol_id":"gh/entireio/entire-brain:Go:internal/cli/setup_daemon_concurrency_test.go:function:TestSupervisedWatchMaintainsItsLogEvenWithNothingToWatch","symbol_name":"TestSupervisedWatchMaintainsItsLogEvenWithNothingToWatch","qualified_name":"TestSupervisedWatchMaintainsItsLogEvenWithNothingToWatch","signature":"func TestSupervisedWatchMaintainsItsLogEvenWithNothingToWatch(t *testing.T)","signals":["body","symbol-name","signature","symbol-usage"],"snippet":"\tpasses := 0\n\tif err := supervisedWatchLoop(context.Background(), io.Discard, f.env, base,"},{"rank":6,"score":80.3013,"file_path":"internal/cli/history_delta_test.go","start_line"