package cli

import (
	"bytes"
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/ashtom/entire-brain/internal/config"
	"github.com/charmbracelet/x/ansi"
	"github.com/spf13/cobra"
)

func execute(t *testing.T, cmd *cobra.Command, args ...string) (string, error) {
	t.Helper()

	var stdout bytes.Buffer
	cmd.SetOut(&stdout)
	cmd.SetErr(&stdout)
	cmd.SetArgs(args)
	err := cmd.Execute()
	return stdout.String(), err
}

func TestFormatJSONRendersStructuredErrors(t *testing.T) {
	cmd := NewRootCommand(Options{Version: "test-version"})
	out, err := execute(t, cmd, "search", "alpha", "--format", "json", "--limit", "0")
	if err == nil {
		t.Fatalf("search succeeded unexpectedly:\n%s", out)
	}
	var envelope commandJSONError
	if decodeErr := json.Unmarshal([]byte(out), &envelope); decodeErr != nil {
		t.Fatalf("--format json error output was not JSON: %v\n%s", decodeErr, out)
	}
	if envelope.Code != "command_failed" || envelope.Message == "" {
		t.Fatalf("unexpected JSON error envelope: %+v", envelope)
	}

	cmd = NewRootCommand(Options{Version: "test-version"})
	out, err = execute(t, cmd, "search", "alpha", "--format", "cli", "--json", "--limit", "0")
	if err == nil {
		t.Fatalf("search succeeded unexpectedly:\n%s", out)
	}
	if json.Valid([]byte(out)) {
		t.Fatalf("--format cli should force plain error output even with --json:\n%s", out)
	}
}

func TestRootWithoutCommandShowsHelp(t *testing.T) {
	cmd := NewRootCommand(Options{Version: "test-version"})
	out, err := execute(t, cmd)
	if err != nil {
		t.Fatalf("execute root: %v", err)
	}
	for _, want := range []string{
		"local, inspectable repository brain",
		"Usage:",
		// Commands are organized into use-case groups instead of one flat list.
		"Set up the brain & agents:",
		"Search & explore the brain:",
		"Durable facts & patterns:",
		"Sessions & conversation memory:",
		"Code & semantic index:",
		"Brain state & maintenance:",
		"Workspaces & sharing:",
		"Miscellaneous:",
		"brief",
		"status",
		"refresh",
		"inspect",
		"mcp",
		"version",
		"workspace",
	} {
		if !strings.Contains(out, want) {
			t.Fatalf("root output missing %q:\n%s", want, out)
		}
	}
	// `doctor` and `config` are PRESENT. They were hidden here as plugin
	// plumbing, and this list pinned that -- while the README documented
	// doctor's exit-code contract in its own section and scripts/install.sh ran
	// both and closed by telling the reader to re-run `entire brain doctor`.
	// TestDocumentedCommandsAreDiscoverable now holds the general rule; this is
	// the direct assertion for the two that were wrong.
	for _, want := range []string{"  doctor ", "  config "} {
		if !strings.Contains(out, want) {
			t.Fatalf("root output should list %q (the docs tell users to run it):\n%s", want, out)
		}
	}
	// Absent from top-level help: the dropped completion generator; removed
	// redundant aliases; and the build stages that now live under `refresh`
	// (sessions, index, seed).
	for _, absent := range []string{
		"  completion ",
		"  context ", "  impact ", "  changes ",
		"  tests ", "  routes ", "  tools ", "  workflows ",
		"  index ", "  seed ", "  sessions ", "  history-index ",
	} {
		Warnings: []string{warning},
		Sources: &brainSources{
			Seed: &seedSourceManifest{GeneratedAt: time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC), SummaryPath: "seed/repo-overview.md"},
			Sessions: &sessionSourceManifest{
				Warnings: []string{warning},
			},
		},
	})
	if strings.Count(readme, warning) != 1 {
		t.Fatalf("warning was not deduplicated:\n%s", readme)
	}
}

func seedFixtureRepo(t *testing.T) string {
	t.Helper()
	repoDir := t.TempDir()
	files := map[string]string{
		"README.md":                       "# Test Repo\n",
		"CLAUDE.md":                       "# Rules\n",
		".github/copilot-instructions.md": "# Copilot\n",
		"package.json":                    `{"scripts":{"dev":"vite","test":"vitest"}}`,
		"mise.toml":                       "[tasks.fmt]\nrun = \"gofmt -w .\"\n\n[tasks.\"test:ci\"]\nrun = '''\ngo test -race ./...\n'''\n",
		"src/main.jsx":                    "export function main() {}\n",
		"src/index.ts":                    "export {}\n",
		"src/__tests__/main.test.js":      "test('x', () => {})\n",
		".env.local":                      "TOKEN=secret\n",
		"dist/generated.js":               "generated\n",
		"package-lock.json":               "{}\n",
	}
	for path, content := range files {
		abs := filepath.Join(repoDir, filepath.FromSlash(path))
		if err := os.MkdirAll(filepath.Dir(abs), 0o700); err != nil {
			t.Fatalf("mkdir %s: %v", path, err)
		}
		if err := os.WriteFile(abs, []byte(content), 0o600); err != nil {
			t.Fatalf("write %s: %v", path, err)
		}
	}
	return repoDir
}

