}"},{"rank":4,"score":78.6055,"file_path":"internal/cli/mcp.go","start_line":1064,"end_line":1068,"focus_line":1068,"snippet_start_line":1064,"snippet_end_line":1068,"symbol_start_line":963,"symbol_end_line":1451,"language":"Go","kind":"function","symbol_id":"gh/entireio/entire-brain:Go:internal/cli/mcp.go:function:handleMCPToolCall","symbol_name":"handleMCPToolCall","qualified_name":"handleMCPToolCall","signature":"func handleMCPToolCall(ctx context.Context, opts Options, raw json.RawMessage) (map[string]any, error)","signals":["body","signature","symbol-usage"],"snippet":"		// otherwise let a prompt-injected host (or a malicious client) run any
