def write_coverage_outputs(
    output: Path,
    summary: dict[str, Any],
    environment: dict[str, Any],
    blocks: dict[str, tuple[int, bool]],
) -> None:
    if output.exists():
        if not output.is_dir():
            raise ValueError("coverage output exists and is not a directory")
        if any(output.iterdir()):
            raise ValueError("coverage output directory must be empty")
    output.mkdir(parents=True, exist_ok=True)
    write_json(output / "environment.json", environment)
    write_json(output / "summary.json", summary)
    write_text(
        output / "combined.out",
        "mode: set\n"
        + "".join(
            f"{location} {statements} {int(hit)}\n"
            for location, (statements, hit) in sorted(blocks.items())
        ),
    )


def verify_required_zero_exit(
    payload: Any,
    key: str,
    label: str,
    location: str,
    failures: list[str],
    exit_report: list[dict[str, Any]],
) -> None:
    present = isinstance(payload, dict) and key in payload
    value = payload.get(key) if present else None
    passed = present and isinstance(value, int) and not isinstance(value, bool) and value == 0
    exit_report.append(
        {
            "input": label,
            "location": location,
            "present": present,
            "value": value,
            "passed": passed,
        }
    )
    if not present:
        failures.append(f"{label} is missing required exit field {location}")
    elif not passed:
        failures.append(f"{label} has nonzero or non-integer exit at {location}: {value!r}")

import json
import sys
import tempfile
import unittest
from contextlib import redirect_stderr, redirect_stdout
from io import StringIO
from pathlib import Path


SCRIPT_DIR = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(SCRIPT_DIR))

import plan_shards  # noqa: E402
import verify_results  # noqa: E402


def write_json(path, value):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value, indent=2) + "\n", encoding="utf-8")


def write_jsonl(path, values):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text("".join(json.dumps(value) + "\n" for value in values), encoding="utf-8")


def write_profile(path, lines):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text("mode: atomic\n" + "".join(f"{line}\n" for line in lines), encoding="utf-8")
    return plan_shards.sha256_file(path)


