func TestBrainBriefRawHistoryProfileAggregatesAndCountsTruncation(t *testing.T) {
	brainDir := t.TempDir()
	sessionDir := filepath.Join(brainDir, "sessions", "main")
	if err := os.MkdirAll(sessionDir, 0o700); err != nil {
