	defer f.Close()
	scanner := newSemanticScanner(f)
	first := true
	symbols := map[string]semanticRecord{}
	for scanner.Scan() {
		if first {
			first = false
			continue
		}
		text := bytes.TrimSpace(scanner.Bytes())
		if len(text) == 0 {
			continue
		}
		var record semanticRecord
		if err := json.Unmarshal(text, &record); err != nil {
			return nil, err
		}
		if record.RecordType == "symbol" {
