	if err != nil {
		t.Fatalf("brief without profile: %v\n%s", err, withoutProfile)
	}
	if _, statErr := os.Stat(profilePath); !os.IsNotExist(statErr) {
		t.Fatalf("unprofiled brief created a sidecar: %v", statErr)
	}
